class LruCache<K, V>(val capacity: Int, private val onEvict: (K, V) -> Unit = { _, _ -> }) {
    init {
        if (capacity < 1) {
            throw IllegalArgumentException("Capacity must be >= 1")
        }
    }

    private var eldestEntryToEvict: MutableMap.MutableEntry<K, V>? = null

    private val map = object : LinkedHashMap<K, V>(capacity, 0.75f, true) {
        override fun removeEldestEntry(eldest: MutableMap.MutableEntry<K, V>?): Boolean {
            if (size > capacity) {
                eldestEntryToEvict = eldest
                return true
            }
            return false
        }

        override fun put(key: K, value: V): V? {
            val old = super.put(key, value)
            if (eldestEntryToEvict != null && !containsKey(key)) {
                // An entry was added and eldest was marked for eviction
                val (k, v) = eldestEntryToEvict!!
                onEvict(k, v)
                eldestEntryToEvict = null
            } else if (eldestEntryToEvict != null && containsKey(key)) {
                // The entry we were about to evict was actually the one being updated? 
                // No, if we're updating an existing key, removeEldestEntry shouldn't have been called for eviction purposes in a way that affects us incorrectly.
                // Actually, if size > capacity after put (new key), eldest is marked.
                // If we are updating an existing key, size doesn't increase, so removeEldestEntry returns false normally.
                // But wait: LinkedHashMap's put() calls super.putVal(), which adds the entry if new, then calls removeEldestEntry.
                // If it's an update, it just replaces and doesn't call removeEldestEntry? Let me check OpenJDK source.
                // In LinkedHashMap.put(): 
                //   e = tab[hash & (n-1)]; while(e!=null) ... if(key.equals(e.key)) { replaceEntryValues(e, value); return old; }
                //   addEntry(hash, key, value, -1); -> which calls createEntry and then checkForOverflow? No.
                // Actually, let's look at the logic more carefully.
                // If the key exists, it updates in place and returns old value. It does NOT call removeEldestEntry.
                // If the key is new, it adds the entry, then calls removeEldestEntry().
                // So if eldestEntryToEvict is set, it means a new entry was added and size > capacity.
                // We should always evict the eldest after put() if eldestEntryToEvict is set and we didn't just update.
                // But how do we know if we updated? If old != null, we updated.
