                    // New entry added
                    val (k, v) = eldestEntryToEvict!!
                    onEvict(k, v)
                }
                eldestEntryToEvict = null
            }
            return old
        }
    }

    operator fun get(key: K): V? {
        return map[key]
    }

    operator fun set(key: K, value: V) {
        map.put(key, value)
    }

