fun toJson(value: Any?, indent: Int = 0): String {
    return buildString {
        serialize(value, this, indent, 0)
    }
}

private fun StringBuilder.serialize(value: Any?, sb: StringBuilder, indent: Int, level: Int) {
    when (value) {
        null -> sb.append("null")
        is Boolean -> sb.append(if (value) "true" else "false")
        is String -> sb.append(escapeString(value))
        is Int -> sb.append(value.toString())
        is Long -> sb.append(value.toString())
        is Float -> {
            val d = value.toDouble()
            if (d.isNaN() || d.isInfinite()) {
                throw IllegalArgumentException("Float value is not finite: $value")
            }
            sb.append(d.toString())
        }
        is Double -> {
            if (value.isNaN() || value.isInfinite()) {
                throw IllegalArgumentException("Double value is not finite: $value")
            }
            sb.append(value.toString())
        }
        is Map<*, *> -> serializeMap(value, sb, indent, level)
        is List<*> -> serializeList(value, sb, indent, level)
        is Array<*> -> serializeList(value.toList(), sb, indent, level)
        is Enum<*> -> sb.append("\"${value.name}\"")
        else -> throw IllegalArgumentException("Unsupported type: ${value::class.java}")
    }
}

private fun StringBuilder.serializeMap(map: Map<*, *>, sb: StringBuilder, indent: Int, level: Int) {
    if (map.isEmpty()) {
        if (indent > 0) {
            sb.append("{}")
        } else {
            sb.append("{}")
        }
        return
    }

    val keys = map.keys.toList()
    // Check that all keys are Strings
    for (key in keys) {
        if (key !is String) {
            throw IllegalArgumentException("Map key must be a String, got: ${key::class.java}")
        }
    }

    if (indent > 0) {
        sb.append("{\n")
        val currentIndent = " ".repeat(level * indent)
        val nextIndent = " ".repeat((level + 1) * indent)
        for ((i, key) in keys.withIndex()) {
            sb.append(nextIndent)
            sb.append("\"$key\": ")
            serialize(map[key], sb, indent, level + 1)
            if (i < keys.size - 1) {
                sb.append(",")
            }
            sb.append("\n")
        }
        sb.append(currentIndent)
        sb.append("}")
    } else {
        sb.append("{")
        for ((i, key) in keys.withIndex()) {
            if (i > 0) sb.append(",")
            sb.append("\"$key\":")
            serialize(map[key], sb, indent, level + 1)
        }
        sb.append("}")
    }
}

private fun StringBuilder.serializeList(list: List<*>, sb: StringBuilder, indent: Int, level: Int) {
    if (list.isEmpty()) {
        sb.append("[]")
        return
    }

    if (indent > 0) {
        sb.append("[\n")
        val currentIndent = " ".repeat(level * indent)
        val nextIndent = " ".repeat((level + 1) * indent)
        for ((i, item) in list.withIndex()) {
            sb.append(nextIndent)
            serialize(item, sb, indent, level + 1)
            if (i < list.size - 1) {
                sb.append(",")
            }
            sb.append("\n")
        }
        sb.append(currentIndent)
        sb.append("]")
    } else {
        sb.append("[")
        for ((i, item) in list.withIndex()) {
            if (i > 0) sb.append(",")
            serialize(item, sb, indent, level + 1)
        }
        sb.append("]")
    }
}

private fun escapeString(value: String): String {
    return buildString {
        append("\"")
        for (char in value) {
            when (char) {
                '"' -> append("\\\"")
                '\\' -> append("\\\\")
                '\b' -> append("\\b")
                '\f' -> append("\\f")
                '\n' -> append("\\n")
                '\r' -> append("\\r")
                '\t' -> append("\\t")
                else -> {
                    val code = char.code
                    if (code < 0x20) {
                        append("\\u")
                        append(String.format("%04x", code))
                    } else {
                        append(char)
                    }
                }
            }
        }
        append("\"")
    }
}
