```kotlin
sealed class Token {
    abstract val pos: Int  // 0-based index of the token's first character
    data class Ident(val name: String, override val pos: Int) : Token()
    data class Str(val value: String, override val pos: Int) : Token()
    data class Num(val value: Double, override val pos: Int) : Token()
    data class Op(val symbol: String, override val pos: Int) : Token()
    data class Paren(val open: Boolean, override val pos: Int) : Token()
}

class TokenizeException(message: String, val pos: Int) : Exception(message)

fun tokenize(input: String): List<Token> {
    val tokens = mutableListOf<Token>()
    var i = 0
    val len = input.length

    // Track if we are at the start or after an operator/paren to allow leading minus
    var prevWasOpOrParen = true

    while (i < len) {
        val c = input[i]

        // Skip whitespace
        if (c.isWhitespace()) {
            i++
            continue
        }

        val startPos = i

        // Check for operators and parentheses (longest match first)
        val twoCharOps = listOf("==", "!=", "<=", ">=", "&&", "||")
        var matchedOp = false

        // Try 2-char operators first
        if (i + 1 < len) {
            val twoChars = input.substring(i, i + 2)
            if (twoCharOps.contains(twoChars)) {
                tokens.add(Token.Op(twoChars, startPos))
                i += 2
                prevWasOpOrParen = true
                matchedOp = true
            }
        }

        // Try single-char operators and parentheses
        if (!matchedOp) {
            when (c) {
                '!' -> {
                    tokens.add(Token.Op("!", startPos))
                    i++
                    prevWasOpOrParen = true
                }
                '<' -> {
                    tokens.add(Token.Op("<", startPos))
                    i++
                    prevWasOpOrParen = true
                }
                '>' -> {
                    tokens.add(Token.Op(">", startPos))
                    i++
                    prevWasOpOrParen = true
                }
                '(' -> {
                    tokens.add(Token.Paren(true, startPos))
                    i++
                    prevWasOpOrParen = true
                }
                ')' -> {
                    tokens.add(Token.Paren(false, startPos))
                    i++
                    prevWasOpOrParen = true
                }
                else -> {
                    // Not an operator/paren, try other tokens
                    prevWasOpOrParen = false

                    // Try identifier
                    if (c.isLetter() || c == '_') {
                        val sbIdent = StringBuilder()
                        sbIdent.append(c)
                        i++
                        while (i < len && (input[i].isLetterOrDigit() || input[i] == '_' || input[i] == '.')) {
                            // Dots are allowed only after the first character
                            sbIdent.append(input[i])
                            i++
                        }
                        val ident = sbIdent.toString()
                        tokens.add(Token.Ident(ident, startPos))
                    }
                    // Try number
                    else if (c.isDigit() || (prevWasOpOrParen && c == '-')) {
                        // Check for leading minus
                        var startNumPos = startPos
                        var hasMinus = false
                        val sbNum = StringBuilder()

                        if (prevWasOpOrParen && c == '-') {
                            hasMinus = true
                            startNumPos = i
                            i++
                            if (i >= len || !input[i].isDigit()) {
                                throw TokenizeException("Invalid number after operator", startPos)
                            }
                        }

                        // Parse digits and optional dot
                        var hasDot = false
                        while (i < len && (input[i].isDigit() || input[i] == '.')) {
                            if (input[i] == '.') {
                                if (hasDot) {
                                    throw TokenizeException("Invalid number format", startNumPos)
                                }
                                hasDot = true
                            }
                            sbNum.append(input[i])
                            i++
                        }

                        val numStr = if (hasMinus) "-" + sbNum.toString() else sbNum.toString()

                        // Validate number format
                        val cleanNumStr = if (hasMinus) numStr.substring(1) else numStr

                        if (cleanNumStr.isEmpty()) {
                            throw TokenizeException("Invalid number", startPos)
                        }

                        // Check for trailing dot: e.g. "5." -> ends with dot
                        if (cleanNumStr.endsWith('.')) {
                            throw TokenizeException("Invalid number format", startNumPos)
                        }

                        try {
                            val value = numStr.toDouble()
                            tokens.add(Token.Num(value, startPos))
                        } catch (e: NumberFormatException) {
                            throw TokenizeException("Invalid number format", startNumPos)
                        }
                    }
                    // Try string
                    else if (c == '"' || c == '\'') {
                        val quoteChar = c
                        i++
                        val sbStr = StringBuilder()
                        var terminated = false
                        while (i < len) {
                            val ch = input[i]
                            if (ch == '\\') {
                                i++
                                if (i >= len) {
                                    throw TokenizeException("Unterminated string", startPos)
                                }
                                val nextCh = input[i]
                                when (nextCh) {
                                    'n' -> sbStr.append('\n')
                                    't' -> sbStr.append('\t')
                                    'r' -> sbStr.append('\r')
                                    '\\' -> sbStr.append('\\')
                                    '"' -> sbStr.append('"')
                                    '\'' -> sbStr.append('\'')
                                    else -> sbStr.append(nextCh)
                                }
                                i++
                            } else if (ch == quoteChar) {
                                i++ // consume closing quote
                                terminated = true
                                break
                            } else {
                                sbStr.append(ch)
                                i++
                            }
                        }

                        if (!terminated) {
                            throw TokenizeException("Unterminated string", startPos)
                        }

                        tokens.add(Token.Str(sbStr.toString(), startPos))
                    }
                    else {
                        throw TokenizeException("Unexpected character: $c", startPos)
                    }
                }
            }
        }
    }

    return tokens
}
