def apply_patch(original: str, diff: str) -> str:
    """
    Apply a unified diff to the original text and return the patched text.
    """
    # Split the diff into lines while preserving newline characters
    diff_lines = _split_lines_with_newline(diff)

    # Find all hunk headers (@@ ...)
    hunk_starts = []
    for i, line in enumerate(diff_lines):
        content = _strip_trailing_newline(line)
        if content.startswith('@@'):
            hunk_starts.append(i)

    if not hunk_starts:
        # No hunks found, return original as-is
        return original

    # Parse each hunk
    hunks = []
    for idx, start_idx in enumerate(hunk_starts):
        header_line = _strip_trailing_newline(diff_lines[start_idx])
        old_start, old_count, new_start, new_count = _parse_hunk_header(header_line)

        # Determine end of this hunk (start of next hunk or end of diff)
        if idx + 1 < len(hunk_starts):
            end_idx = hunk_starts[idx + 1]
        else:
            end_idx = len(diff_lines)

        body_lines = diff_lines[start_idx + 1:end_idx]

        hunks.append({
            'old_start': old_start,
            'old_count': old_count,
            'new_start': new_start,
            'new_count': new_count,
            'body': body_lines,
        })

    # Split original into lines keeping newlines
    original_lines = _split_lines_with_newline(original)

    # Apply hunks in order
    result_lines = []
    orig_idx = 0

    for hunk in hunks:
        old_start = hunk['old_start']
        old_count = hunk['old_count']
        new_count = hunk['new_count']
        body = hunk['body']

        # Convert to 0-based index for original_lines
        expected_orig_idx = old_start - 1

        if orig_idx != expected_orig_idx:
            raise ValueError(
                f"Hunk expects old start at line {old_start} (index {expected_orig_idx}), "
                f"but current position is index {orig_idx}"
            )

        # Process hunk body
        old_consumed = 0
        new_produced = 0

        # Track no-newline-at-end for the last old/new line in this hunk
        last_old_no_newline = False
        last_new_no_newline = False

        i = 0
        while i < len(body):
            raw_line = body[i]
            content = _strip_trailing_newline(raw_line)

            if content.startswith('\\'):
                # "\ No newline at end of file"
                # Look back to find the last actual content line (not another marker)
                j = i - 1
                while j >= 0 and _strip_trailing_newline(body[j]).startswith('\\'):
                    j -= 1

                if j < 0:
                    raise ValueError("No newline marker without preceding content")

                prev_content = _strip_trailing_newline(body[j])

                if prev_content.startswith('-') or prev_content.startswith(' '):
                    last_old_no_newline = True
                elif prev_content.startswith('+'):
                    last_new_no_newline = True
                else:
                    raise ValueError(f"Unexpected line before no-newline marker: {repr(prev_content)}")

                i += 1
                continue

            if content.startswith(' '):
                # Context line
                old_line_text = content[1:]  # Remove leading space

                if old_consumed >= old_count:
                    raise ValueError(f"Too many old lines consumed in hunk (expected {old_count})")

                if orig_idx < len(original_lines):
                    actual_orig_line = original_lines[orig_idx]
                    actual_orig_content = _strip_trailing_newline(actual_orig_line)

                    if actual_orig_content != old_line_text:
                        raise ValueError(
                            f"Context/removed line mismatch at index {orig_idx}: "
                            f"expected '{old_line_text}', got '{actual_orig_content}'"
                        )

                    # Add this line to result (as new content)
                    if last_new_no_newline and new_produced == new_count - 1:
                        # Last new line, no trailing newline
                        result_lines.append(actual_orig_content)
                    else:
                        result_lines.append(actual_orig_line)

                    orig_idx += 1
                    old_consumed += 1
                    new_produced += 1

                    # Reset last_old_no_newline since we processed this old line
                    if old_consumed == old_count and last_old_no_newline:
                        pass  # Already handled
                else:
                    raise ValueError(f"Unexpected end of original file at context line")

            elif content.startswith('-'):
                # Removed line
                old_line_text = content[1:]

                if old_consumed >= old_count:
                    raise ValueError(f"Too many removed lines in hunk")

                if orig_idx < len(original_lines):
                    actual_orig_line = original_lines[orig_idx]
                    actual_orig_content = _strip_trailing_newline(actual_orig_line)

                    if actual_orig_content != old_line_text:
                        raise ValueError(
                            f"Removed line mismatch at index {orig_idx}: "
                            f"expected '{old_line_text}', got '{actual_orig_content}'"
                        )

                    orig_idx += 1
                    old_consumed += 1

                    if last_old_no_newline and old_consumed == old_count:
                        pass  # No newline on this removed line (already consumed)
                else:
                    raise ValueError(f"Unexpected end of original file at removed line")

            elif content.startswith('+'):
                # Added line
                new_line_text = content[1:]

                if new_produced >= new_count:
                    raise ValueError(f"Too many added lines in hunk")

                if last_new_no_newline and new_produced == new_count - 1:
                    # Last new line, no trailing newline
                    result_lines.append(new_line_text)
                else:
                    result_lines.append(new_line_text + '\n')

                new_produced += 1

            else:
                raise ValueError(f"Unexpected line in hunk body: {repr(content)}")

            i += 1

        # Verify counts
        if old_consumed != old_count:
            raise ValueError(
                f"Hunk old count mismatch: expected {old_count}, consumed {old_consumed}"
            )
        if new_produced != new_count:
            raise ValueError(
                f"Hunk new count mismatch: expected {new_count}, produced {new_produced}"
            )

    # Append remaining original lines after last hunk
    while orig_idx < len(original_lines):
        result_lines.append(original_lines[orig_idx])
        orig_idx += 1

    return ''.join(result_lines)


def _split_lines_with_newline(text: str) -> list:
    """
    Split text into lines, keeping the newline characters as part of each line.

    "abc\ndef\n" -> ["abc\n", "def\n"]
    "abc\ndef"   -> ["abc\n", "def"]
    ""           -> []
    "\n"         -> ["\n"]
    """
    if not text:
        return []

    lines = []
    start = 0
    for i, ch in enumerate(text):
        if ch == '\n':
            lines.append(text[start:i + 1])
            start = i + 1

    if start < len(text):
        lines.append(text[start:])

    return lines


def _strip_trailing_newline(line: str) -> str:
    """Remove trailing newline from a line."""
    if line.endswith('\n'):
        return line[:-1]
    return line


def _parse_hunk_header(header: str) -> tuple:
    """
    Parse a hunk header like '@@ -l,s +l,s @@ optional text'
    Returns (old_start, old_count, new_start, new_count)
    """
    parts = header.split('@@', 2)
    if len(parts) < 2:
        raise ValueError(f"Invalid hunk header: {repr(header)}")

    ranges_part = parts[1].strip()

    # Split into old and new range parts
    range_parts = ranges_part.split(None, 1)
    if len(range_parts) < 2:
        raise ValueError(f"Invalid hunk header ranges: {repr(ranges_part)}")

    old_range_str = range_parts[0]
    new_range_str = range_parts[1]

    if not old_range_str.startswith('-'):
        raise ValueError(f"Old range should start with -: {repr(old_range_str)}")
    if not new_range_str.startswith('+'):
        raise ValueError(f"New range should start with +: {repr(new_range_str)}")

    old_start, old_count = _parse_range(old_range_str[1:])
    new_start, new_count = _parse_range(new_range_str[1:])

    return (old_start, old_count, new_start, new_count)


def _parse_range(range_str: str) -> tuple:
    """
    Parse a range like 'l' or 'l,s'.
    Returns (start, count).
    If only l is given, count defaults to 1.
    """
    if ',' in range_str:
        parts = range_str.split(',', 1)
        try:
            start = int(parts[0])
            count = int(parts[1])
        except ValueError:
            raise ValueError(f"Invalid range format: {repr(range_str)}")
    else:
        try:
            start = int(range_str)
            count = 1
        except ValueError:
            raise ValueError(f"Invalid range format: {repr(range_str)}")

    return (start, count)
