import copy


def merge(base: dict, *overrides: dict) -> dict:
    """
    Deep merge configuration layers where later overrides win.

    - Dicts are merged recursively.
    - Non-dict values in an override replace the base value (lists are replaced, not concatenated).
    - A key whose override value is None deletes that key from the result.
    - A key ending in '+' appends items to the base list (e.g., {"plugins+": ["x"]}).
      If the base value exists and is not a list, raise TypeError.
      The '+' key itself never appears in the result.
    - Inputs must not be mutated, and the result must not share mutable dicts/lists with the inputs.
    """
    # Start with a deep copy of the base
    result = copy.deepcopy(base) if base else {}

    for override in overrides:
        if override is None:
            continue
        for key, value in override.items():
            if key.endswith('+'):
                # Handle append semantics
                list_key = key[:-1]  # Remove the '+' suffix

                # Check if the base (current result) has this key
                if list_key in result:
                    base_value = result[list_key]
                    if not isinstance(base_value, list):
                        raise TypeError(f"Key '{list_key}' exists and is not a list, cannot append")
                    # Append the new items to the existing list
                    if value is not None:
                        # Deep copy the incoming list items to avoid sharing
                        result[list_key] = base_value + copy.deepcopy(value)
                else:
                    # Key doesn't exist in result, create a new list from the override
                    if value is not None:
                        result[list_key] = copy.deepcopy(value)
                    # If value is None for a '+' key, it means delete? 
                    # The spec says "A key whose override value is None deletes that key"
                    # So if we have {"plugins+": None}, it should delete plugins
                    else:
                        if list_key in result:
                            del result[list_key]
            else:
                if value is None:
                    # Delete the key if it exists
                    if key in result:
                        del result[key]
                elif isinstance(value, dict):
                    # Recursively merge dicts
                    if key not in result or not isinstance(result[key], dict):
                        # If key doesn't exist or isn't a dict, replace with deep copy of override value
                        result[key] = copy.deepcopy(value)
                    else:
                        # Both are dicts, merge recursively
                        result[key] = merge(result[key], value)
                else:
                    # Non-dict, non-None value replaces the base value
                    result[key] = copy.deepcopy(value) if isinstance(value, (dict, list)) else value

    return result
