def flatten(obj, sep="."):
    """
    Turns nested dicts and lists into a flat dict with path keys.

    Args:
        obj: The top-level object (must be a dict).
        sep: The separator to use for joining path segments.

    Returns:
        A flat dictionary with path keys.

    Raises:
        TypeError: If the top-level object is not a dict.
        ValueError: If any key contains the separator.
    """
    if not isinstance(obj, dict):
        raise TypeError("Top-level object must be a dict")

    result = {}

    def _flatten(current, path_parts):
        if isinstance(current, dict):
            if not current:
                # Empty dict is kept as leaf
                key = sep.join(path_parts) if path_parts else ""
                result[key] = {}
                return
            for key in current:
                if sep in key:
                    raise ValueError(f"Key '{key}' contains separator '{sep}'")
                _flatten(current[key], path_parts + [key])
        elif isinstance(current, list):
            if not current:
                # Empty list is kept as leaf
                key = sep.join(path_parts) if path_parts else ""
                result[key] = []
                return
            for idx, item in enumerate(current):
                _flatten(item, path_parts + [str(idx)])
        else:
            # Any other value is a leaf
            key = sep.join(path_parts) if path_parts else ""
            result[key] = current

    _flatten(obj, [])
    return result


def unflatten(flat: dict, sep="."):
    """
    Inverse of flatten: converts a flat dict with path keys back into nested dicts/lists.

    Args:
        flat: A flat dictionary with path keys.
        sep: The separator used in the path keys.

    Returns:
        A nested dict/list structure.

    Raises:
        ValueError: If there are conflicts (e.g., a key is both a value and a prefix for another key),
                    or if list indices are not dense, or if an index has leading zeros.
    """
    if not isinstance(flat, dict):
        raise TypeError("Input must be a dict")

    # Parse all keys into their path segments
    parsed_keys = []
    for key in flat:
        if key == "":
            # Empty key means the top-level itself is a leaf value
            # This is an edge case. If there's only one key and it's empty, return that value.
            parsed_keys.append(([], key))
        else:
            segments = key.split(sep)
            parsed_keys.append((segments, flat[key]))

    if not parsed_keys:
        return {}

    # Check for the special case where the only key is empty string
    if len(parsed_keys) == 1 and parsed_keys[0][0] == []:
        return parsed_keys[0][1]

    # Build the nested structure
    root = {}

    # Sort parsed keys by length, then lexicographically to process in order
    # Actually, we need to insert them carefully. Let's process each key and build up.

    for segments, value in parsed_keys:
        if not segments:
            continue

        # Validate segments
        current = root
        for i, seg in enumerate(segments):
            is_last = (i == len(segments) - 1)

            # Check if segment is a list index (non-negative integer without leading zeros)
            is_index = False
            if seg.isdigit() or (seg.startswith('-') and False):  # Only non-negative
                # Check for leading zeros: "0" is ok, "00", "01" are not
                if len(seg) > 1 and seg[0] == '0':
                    raise ValueError(f"Index '{seg}' has leading zeros")
                try:
                    int_val = int(seg)
                    if int_val < 0:
                        raise ValueError(f"Negative index '{seg}'")
                    is_index = True
                except ValueError:
                    pass

            if is_last:
                # This is the leaf node
                if seg in current and isinstance(current[seg], dict):
                    # Conflict: existing key is a dict (prefix for another path) but we're trying to set it as a value
                    raise ValueError(f"Conflict at key '{sep.join(segments)}': existing dict cannot be overwritten with value")
                elif seg in current and not isinstance(current[seg], dict):
                    # Conflict: existing value is being overwritten
                    raise ValueError(f"Conflict at key '{sep.join(segments)}': existing value cannot be overwritten")
                else:
                    current[seg] = value
            else:
                # Intermediate node
                if seg not in current:
                    if is_index:
                        current[seg] = []
                    else:
                        current[seg] = {}

                next_node = current[seg]
                if is_index and isinstance(next_node, dict):
                    raise ValueError(f"Conflict at segment '{seg}': expected list but found dict")
                elif not is_index and isinstance(next_node, list):
                    raise ValueError(f"Conflict at segment '{seg}': expected dict but found list")

                current = next_node

    # Now validate that all lists are dense
    def _validate_lists(obj):
        if isinstance(obj, dict):
            for key in obj:
                val = obj[key]
                if isinstance(val, list):
                    # Check density: indices must be exactly 0..n-1
                    if len(val) > 0:
                        expected_indices = set(range(len(val)))
                        actual_indices = set()
                        for i, item in enumerate(val):
                            actual_indices.add(i)
                        if actual_indices != expected_indices:
                            raise ValueError(f"List at path is not dense")
                    _validate_lists(obj[key])
                elif isinstance(val, dict):
                    _validate_lists(val)
        elif isinstance(obj, list):
            for item in obj:
                _validate_lists(item)

    _validate_lists(root)

