def evaluate(expr: str, env: dict[str, float] | None = None) -> int | float:
    """
    Evaluate an expression string according to the specified grammar.

    Grammar precedence (lowest to highest):
    1. Conditional: a ? b : c (right-associative)
    2. Logical OR: ||, AND: && (short-circuit)
    3. Comparisons: == != < <= > >= (non-associative)
    4. Addition/Subtraction: + - (left-associative)
    5. Multiplication/Division/Modulo: * / % (left-associative)
    6. Unary: - + ! 
    7. Power: ^ (right-associative, binds tighter than unary minus on left)
    8. Atoms: literals, identifiers, function calls, parentheses
    """

    class Token:
        def __init__(self, type_, value):
            self.type = type_
            self.value = value

        def __repr__(self):
            return f"Token({self.type}, {self.value!r})"

    class LexerError(Exception):
        pass

    class ParserError(Exception):
        pass

    def tokenize(s: str) -> list[Token]:
        tokens = []
        i = 0
        n = len(s)

        while i < n:
            # Skip whitespace
            if s[i].isspace():
                i += 1
                continue

            # Check for two-character operators first
            if i + 1 < n:
                two = s[i:i+2]
                if two == '||':
                    tokens.append(Token('OR', '||'))
                    i += 2
                    continue
                elif two == '&&':
                    tokens.append(Token('AND', '&&'))
                    i += 2
                    continue

            # Single character operators
            ch = s[i]
            if ch in '+-*/%^=!<>?:()':
                tokens.append(Token('OP', ch))
                i += 1
                continue

            # Number literal (integer or decimal)
            if ch.isdigit() or (ch == '.' and i + 1 < n and s[i+1].isdigit()):
                j = i
                has_dot = False
                while j < n:
                    c = s[j]
                    if c.isdigit():
                        j += 1
                    elif c == '.':
                        if has_dot:
                            break
                        has_dot = True
                        j += 1
                    else:
                        break
                num_str = s[i:j]
                try:
                    if has_dot:
                        value = float(num_str)
                        # If it's a whole number, store as int-like but we'll convert later
                        # Actually, let's keep it as float for now and handle int conversion at the end
                        # But the spec says integer literals are ints, decimal are floats
                        # Let's try to parse as int first if no dot
                    else:
                        value = int(num_str)
                except ValueError:
                    raise LexerError(f"Invalid number: {num_str}")
                tokens.append(Token('NUMBER', value))
                i = j
                continue

            # Identifier or keyword
            if ch.isalpha() or ch == '_':
                j = i
                while j < n and (s[j].isalnum() or s[j] == '_'):
                    j += 1
                ident = s[i:j]
                tokens.append(Token('IDENT', ident))
                i = j
                continue

            raise LexerError(f"Unexpected character: {ch!r} at position {i}")

        return tokens

    class Parser:
        def __init__(self, tokens: list[Token], env: dict[str, float] | None):
            self.tokens = tokens
            self.pos = 0
            self.env = env if env is not None else {}

        def peek(self) -> Token | None:
            if self.pos < len(self.tokens):
                return self.tokens[self.pos]
            return None

        def advance(self) -> Token:
            tok = self.peek()
            if tok is None:
                raise ParserError("Unexpected end of input")
            self.pos += 1
            return tok

        def expect(self, type_: str, value=None) -> Token:
            tok = self.peek()
            if tok is None:
                raise ParserError(f"Expected {type_} but got end of input")
            if tok.type != type_:
                raise ParserError(f"Expected {type_} but got {tok.type}")
            if value is not None and tok.value != value:
                raise ParserError(f"Expected {value!r} but got {tok.value!r}")
            return self.advance()

        def at_end(self) -> bool:
            return self.pos >= len(self.tokens)

        def parse(self):
            if not self.tokens:
                raise SyntaxError("Empty input")

            result = self.parse_conditional()

            # Check for trailing tokens
            if not self.at_end():
                tok = self.peek()
                raise SyntaxError(f"Unexpected token after expression: {tok}")

            return result

        def parse_conditional(self):
            """Parse conditional expressions: a ? b : c (right-associative)"""
            left = self.parse_logical_or()

            while self.peek() is not None and self.peek().type == 'OP' and self.peek().value == '?':
                self.advance()  # consume '?'
                true_branch = self.parse_conditional()  # right-associative
                self.expect('OP', ':')
                false_branch = self.parse_conditional()  # right-associative

                # Evaluate left (condition)
                cond_val = left
                if cond_val != 0:
                    left = true_branch
                else:
                    left = false_branch

            return left

        def parse_logical_or(self):
            """Parse || and && with short-circuit evaluation"""
            left = self.parse_logical_and()

            while self.peek() is not None and self.peek().type == 'OP' and self.peek().value in ('||', '&&'):
                op = self.advance().value

                if op == '||':
                    # Short-circuit: if left is truthy (non-zero), don't evaluate right
                    if left != 0:
                        # Need to skip the right side properly - parse it but discard
                        self.parse_logical_and()
                        left = 1
                    else:
                        right = self.parse_logical_and()
                        if right != 0:
                            left = 1
                        else:
                            left = 0
                elif op == '&&':
                    # Short-circuit: if left is falsy (zero), don't evaluate right
                    if left == 0:
                        # Skip the right side
                        self.parse_logical_and()
                        left = 0
                    else:
                        right = self.parse_logical_and()
                        if right != 0:
                            left = 1
                        else:
                            left = 0

            return left

        def parse_logical_and(self):
            """Parse &&"""
            left = self.parse_comparison()

            while self.peek() is not None and self.peek().type == 'OP' and self.peek().value == '&&':
                self.advance()
                right = self.parse_comparison()
                if left != 0 and right != 0:
                    left = 1
                else:
                    left = 0

            return left

        def parse_comparison(self):
            """Parse comparison operators (non-associative)"""
            left = self.parse_additive()

            while self.peek() is not None and self.peek().type == 'OP' and self.peek().value in ('==', '!=', '<', '<=', '>', '>='):
                op = self.advance().value
                right = self.parse_additive()

                if op == '==':
                    left = 1 if (left == right) else 0
                elif op == '!=':
                    left = 1 if (left != right) else 0
                elif op == '<':
                    left = 1 if (left < right) else 0
                elif op == '<=':
                    left = 1 if (left <= right) else 0
                elif op == '>':
                    left = 1 if (left > right) else 0
                elif op == '>=':
                    left = 1 if (left >= right) else 0

            return left

        def parse_additive(self):
            """Parse + and - (left-associative)"""
            left = self.parse_multiplicative()

            while self.peek() is not None and self.peek().type == 'OP' and self.peek().value in ('+', '-'):
                op = self.advance()
                right = self.parse_multiplicative()

                if op.value == '+':
                    left = left + right
                else:
                    left = left - right

            return left

        def parse_multiplicative(self):
            """Parse *, /, % (left-associative)"""
            left = self.parse_unary()

            while self.peek() is not None and self.peek().type == 'OP' and self.peek().value in ('*', '/', '%'):
                op = self.advance()
                right = self.parse_unary()

                if op.value == '*':
                    left = left * right
                elif op.value == '/':
                    if right == 0:
                        raise ZeroDivisionError("division by zero")
                    # / on two ints gives int when it divides exactly, else float
                    if isinstance(left, int) and isinstance(right, int):
                        if left % right == 0:
                            left = left // right
                        else:
                            left = left / right
                    else:
                        left = left / right
                elif op.value == '%':
                    if right == 0:
                        raise ZeroDivisionError("modulo by zero")
                    # Python semantics for %
                    left = left % right

            return left

        def parse_unary(self):
            """Parse unary -, +, !"""
            tok = self.peek()

            if tok is not None and tok.type == 'OP' and tok.value in ('-', '+', '!'):
                op = self.advance().value

                operand = self.parse_unary()  # recursive for chaining like --x

                if op == '-':
                    return -operand
                elif op == '+':
                    return +operand
                elif op == '!':
                    return 1 if operand == 0 else 0

            return parse_power()

        def parse_power(self):
            """Parse power ^ (right-associative)"""
            base = self.parse_atom()

            if self.peek() is not None and self.peek().type == 'OP' and self.peek().value == '^':
                self.advance()
                exp = self.parse_power()  # right-associative
                return base ** exp

            return base

        def parse_atom(self):
            """Parse atoms: literals, identifiers, function calls, parentheses"""
            tok = self.peek()

            if tok is None:
                raise ParserError("Unexpected end of input")

            # Parenthesized expression
            if tok.type == 'OP' and tok.value == '(':
                self.advance()  # consume '('
                expr = self.parse_conditional()
                self.expect('OP', ')')
                return expr

            # Number literal
            if tok.type == 'NUMBER':
                self.advance()
                return tok.value

            # Identifier
            if tok.type == 'IDENT':
                ident = self.advance().value

                # Check for function call
                if self.peek() is not None and self.peek().type == 'OP' and self.peek().value == '(':
                    return self.parse_function_call(ident)

                # Variable lookup
                if ident not in self.env:
                    raise NameError(f"Undefined variable or function: {ident}")
                return self.env[ident]

            raise ParserError(f"Unexpected token: {tok}")

        def parse_function_call(self, name: str):
            """Parse a function call like min(...)"""
            self.expect('OP', '(')

            # Parse arguments
            args = []
            if self.peek() is not None and self.peek().type != 'OP' or (self.peek() and self.peek().value != ')'):
                args.append(self.parse_conditional())
                while self.peek() is not None and self.peek().type == 'OP' and self.peek().value == ',':
                    self.advance()  # consume ','
                    args.append(self.parse_conditional())

            self.expect('OP', ')')

            if name == 'min':
                if len(args) < 1:
                    raise SyntaxError("min() requires at least 1 argument")
                return min(args)
            elif name == 'max':
                if len(args) < 1:
                    raise SyntaxError("max() requires at least 1 argument")
                return max(args)
            elif name == 'abs':
                if len(args) != 1:
                    raise SyntaxError("abs() requires exactly 1 argument")
                return abs(args[0])
            else:
                raise NameError(f"Undefined function: {name}")

    # Tokenize
    tokens = tokenize(expr)

    # Parse and evaluate
    parser = Parser(tokens, env)
    result = parser.parse()

    return result
