        # Check if we need to include the previous interval (touching or overlapping)
        if i > 0 and self._iv[i - 1][1] >= start:
            i -= 1
        j = i
        while j < len(self._iv) and self._iv[j][0] < end:
            start = min(start, self._iv[j][0])
            end = max(end, self._iv[j][1])
            j += 1
        self._iv[i:j] = [(start, end)]

    def remove(self, start, end):
        if start >= end:
            return
        out = []
        for s, e in self._iv:
            if e <= start or s >= end:
                out.append((s, e))
                continue
            # There is overlap between [s,e) and [start,end)
            if s < start:
                out.append((s, start))
            if e > end:
                out.append((end, e))
        self._iv = out

    def contains(self, x):
        i = bisect.bisect_left(self._iv, (x,))
        if i < len(self._iv) and self._iv[i][0] <= x < self._iv[i][1]:
