        # bisect_left finds the first index where element >= x. (2,4) < (3,) because 2 < 3. So all elements before index 1 are less than (3,). The list has one element at index 0. So bisect_left returns 1. Then i=1 which is len(self._iv), so it returns False. But 3 is in [2,4)!
        # This is a bug! We need to check the previous interval as well.
        if i > 0 and self._iv[i - 1][0] <= x < self._iv[i - 1][1]:
            return True
        return False

    def free(self, lo, hi):
        if lo >= hi:
            return []
        gaps = []
        cur = lo
        for s, e in self._iv:
            if s > cur and cur < hi:
                gaps.append((cur, min(s, hi)))
            if e > cur:
                cur = max(cur, e)
            if cur >= hi:
