        # Check current interval if it exists
        if i < len(self._iv) and self._iv[i][0] <= x < self._iv[i][1]:
            return True
        # Check previous interval
        if i > 0 and self._iv[i - 1][0] <= x < self._iv[i - 1][1]:
            return True
        return False

    def free(self, lo, hi):
        if lo >= hi:
            return []
        gaps = []
        cur = lo
        for s, e in self._iv:
            # Only consider intervals that overlap with [cur, hi)
            if s >= hi:
                break
            if e <= cur:
                continue
            # The interval [s, e) overlaps with the current gap region [cur, ...)
            # The gap ends at min(s, hi) if s > cur
            if s > cur:
                end_gap = min(s, hi)
                gaps.append((cur, end_gap))
            # Advance cur past this interval
            if e > cur:
                cur = max(cur, e)
        if cur < hi:
            gaps.append((cur, hi))
        return gaps

    def __iter__(self):
        return iter(self._iv)

    def __len__(self):
        return len(self._iv)
