import heapq
from collections import defaultdict


def route(grid: list[str]) -> tuple[int, str] | None:
    """
    Find the cheapest path from S to E in the grid.

    Returns (total_cost, moves) for the cheapest path where among all cheapest paths,
    moves is lexicographically smallest over D < L < R < T < U.
    Returns None if E is unreachable.
    """
    # Validate and parse the grid
    if not grid or not all(isinstance(row, str) for row in grid):
        raise ValueError("Grid must be a non-empty list of strings")

    rows = len(grid)
    cols = len(grid[0]) if grid else 0

    if cols == 0:
        raise ValueError("Grid rows must have equal length and be non-empty")

    for row in grid:
        if len(row) != cols:
            raise ValueError("Ragged rows detected")

    start = None
    end = None
    pad_locations = defaultdict(list)  # letter -> list of (r, c)

    for r in range(rows):
        for c in range(cols):
            ch = grid[r][c]
            if ch == 'S':
                if start is not None:
                    raise ValueError("More than one S found")
                start = (r, c)
            elif ch == 'E':
                if end is not None:
                    raise ValueError("More than one E found")
                end = (r, c)
            elif ch == '#':
                pass  # wall
            elif ch == '.':
                pass
            elif ch.isdigit() and '1' <= ch <= '9':
                pass
            elif ch.islower():
                pad_locations[ch].append((r, c))
            else:
                raise ValueError(f"Unknown character: {ch}")

    if start is None:
        raise ValueError("No S found")
    if end is None:
        raise ValueError("No E found")

    # Validate pad locations: each letter appears exactly 0 or 2 times
    for letter, locs in pad_locations.items():
        if len(locs) != 0 and len(locs) != 2:
            raise ValueError(f"Pad '{letter}' appears {len(locs)} times, expected 0 or 2")

    # Build teleport map: (r, c) -> other (r', c') for pads
    teleport = {}
    for letter, locs in pad_locations.items():
        if len(locs) == 2:
            r1, c1 = locs[0]
            r2, c2 = locs[1]
            teleport[(r1, c1)] = (r2, c2)
            teleport[(r2, c2)] = (r1, c1)

    # Cost function for entering a cell
    def cell_cost(r, c):
        ch = grid[r][c]
        if ch == 'S' or ch == 'E':
            return 1
        elif ch == '#':
            return None  # wall, can't enter
        elif ch == '.':
            return 1
        elif ch.isdigit():
            return int(ch)
        elif ch.islower():
            return 1
        else:
            raise ValueError(f"Unknown character at ({r}, {c}): {ch}")

    # Directions in lexicographic order: D, L, R, U
    directions = [
        ('D', 1, 0),
        ('L', 0, -1),
        ('R', 0, 1),
        ('U', -1, 0),
    ]

    # State: (r, c)
    # We need to find the shortest path with minimum cost, and among those, 
    # lexicographically smallest move string.
    # Use Dijkstra-like approach where priority is (cost, move_string).
    # But move strings can be long, so we need a smarter approach.

    # Key insight: Among all paths with the same minimal cost, we want the 
    # lexicographically smallest sequence of moves. Since D < L < R < T < U,
    # we should prefer D moves over L, etc.

    # We can use a modified Dijkstra where the priority is (cost, move_sequence).
    # But storing full move sequences is expensive. Instead, we can use the fact
    # that when costs are equal, we want lex smallest. 

    # Alternative: Use Dijkstra with state (r, c) and track (min_cost, best_moves_for_that_cost).
    # When we find a new path to a cell with the same cost but lex smaller moves, update.

    # Let's use a priority queue with entries (cost, move_string, r, c).
    # To avoid memory issues, note that grids are up to 60x60 = 3600 cells.
    # The number of states is manageable if we prune properly.

    # However, the move string can be long. Let's think about this differently.

    # We can use a standard Dijkstra where distance[r][c] = (min_cost, best_move_string).
    # When relaxing an edge:
    #   new_cost = current_cost + step_cost
    #   new_moves = current_moves + direction_char
    #   If new_cost < dist[new_r][new_c].cost, update.
    #   If new_cost == dist[new_r][new_c].cost and new_moves < dist[new_r][new_c].moves, update.

    # Since we process in order of increasing cost (Dijkstra), when we first reach a cell with a certain cost,
    # that's the minimum cost. But there might be multiple paths with the same min cost, and we need the lex smallest.

    # Standard Dijkstra guarantees that when we extract a node, we have the shortest distance.
    # For lexicographic tie-breaking among equal costs, we can use a custom comparator in the heap.

    # Priority: (cost, move_string, r, c)
    # The move_string comparison handles the lex ordering.

    # But move strings can be very long. Let's see if this is practical.
    # In the worst case, path length could be O(rows * cols). For 60x60, that's 3600 chars.
    # Comparing such strings in the heap might be slow but should still work for 1 second.

    import heapq

    start_r, start_c = start
    end_r, end_c = end

    # dist[r][c] = (min_cost, best_move_string)
    dist = {}
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != '#':
                dist[(r, c)] = (float('inf'), "")

    # Priority queue: (cost, move_string, r, c)
    initial_cost = 1  # Starting on S costs 1? No, we start AT S. The cost to enter S is not incurred.
    # Wait, re-reading: "Moving into a cell costs that cell's cost". We start at S, so we don't move INTO S.
    # So the initial state has cost 0 and empty moves.

    pq = [(0, "", start_r, start_c)]
    dist[(start_r, start_c)] = (0, "")

    while pq:
        cost, moves, r, c = heapq.heappop(pq)

        # If we popped a state that's worse than what we already know, skip
        if (r, c) in dist:
            stored_cost, stored_moves = dist[(r, c)]
            if cost > stored_cost:
                continue
            if cost == stored_cost and moves > stored_moves:
                continue

        # Check if we reached the end
        if r == end_r and c == end_c:
            return (cost, moves)

        # Try all 4 directions
        for dir_char, dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                ch = grid[nr][nc]
                if ch == '#':
                    continue
                step_cost = cell_cost(nr, nc)
                new_cost = cost + step_cost
                new_moves = moves + dir_char

                # Check if this is an improvement
                if (nr, nc) in dist:
                    stored_cost, stored_moves = dist[(nr, nc)]
                    if new_cost < stored_cost or (new_cost == stored_cost and new_moves < stored_moves):
                        dist[(nr, nc)] = (new_cost, new_moves)
                        heapq.heappush(pq, (new_cost, new_moves, nr, nc))
                else:
                    dist[(nr, nc)] = (new_cost, new_moves)
                    heapq.heappush(pq, (new_cost, new_moves, nr, nc))

        # Try teleport if on a pad
        if (r, c) in teleport:
            tr, tc = teleport[(r, c)]
            # Teleport costs 2
            new_cost = cost + 2
            new_moves = moves + 'T'

            if (tr, tc) in dist:
                stored_cost, stored_moves = dist[(tr, tc)]
                if new_cost < stored_cost or (new_cost == stored_cost and new_moves < stored_moves):
                    dist[(tr, tc)] = (new_cost, new_moves)
                    heapq.heappush(pq, (new_cost, new_moves, tr, tc))
            else:
                dist[(tr, tc)] = (new_cost, new_moves)
                heapq.heappush(pq, (new_cost, new_moves, tr, tc))

    return None
