def load_ini(text: str) -> dict[str, dict[str, str]]:
    """
    Parse an INI-like configuration string into a nested dictionary.

    Returns:
        dict[section][key] = value
        Keys are lowercased and trimmed. Sections are case-sensitive and trimmed.
        Values are trimmed (unless quoted), with quotes removed if present.
    """
    lines = text.split('\n')

    # Parse the file into a structure: list of (section, key, raw_value, line_number)
    # We'll also track raw values before interpolation for continuation handling

    result: dict[str, dict[str, str]] = {}  # section -> {key -> value}
    current_section = ""

    # For tracking continuations: we need to know the last entry's key in the current section
    # and its line number for error reporting.
    last_entry_info = None  # (section, key, raw_value_so_far, start_line) or None

    i = 0
    while i < len(lines):
        line = lines[i]
        line_num = i + 1  # 1-based

        stripped = line.strip()

        # Skip empty lines and comment-only lines
        if not stripped:
            # Blank lines end continuation
            last_entry_info = None
            i += 1
            continue

        if stripped.startswith('#') or stripped.startswith(';'):
            # Comment line, ends continuation
            last_entry_info = None
            i += 1
            continue

        # Check for section header
        if stripped.startswith('['):
            # End any pending continuation
            last_entry_info = None

            # Find the closing bracket
            close_idx = stripped.find(']')
            if close_idx == -1:
                raise ValueError(f"line {line_num}: unclosed section header")

            section_name = stripped[1:close_idx].strip()
            current_section = section_name
            if current_section not in result:
                result[current_section] = {}
            i += 1
            continue

        # Check for continuation line: starts with whitespace and there's a pending entry
        if line != stripped and last_entry_info is not None:
            # This is a continuation line
            cont_value = stripped  # trimmed
            section, key, raw_val, start_ln = last_entry_info
            new_raw = raw_val + '\n' + cont_value
            last_entry_info = (section, key, new_raw, start_ln)
            i += 1
            continue

        # Otherwise, it should be a key-value pair
        if last_entry_info is not None:
            # A non-continuation, non-blank, non-comment, non-section line after an entry
            # means the continuation ended. We finalize the previous entry now.
            _finalize_entry(result, last_entry_info)
            last_entry_info = None

        # Parse key = value or key : value
        sep_idx = -1
        sep_char = None
        # Find first '=' or ':' that is not inside quotes
        in_quotes = False
        for ci, ch in enumerate(stripped):
            if ch == '"':
                in_quotes = not in_quotes
            elif not in_quotes and (ch == '=' or ch == ':'):
                sep_idx = ci
                sep_char = ch
                break

        if sep_idx == -1:
            raise ValueError(f"line {line_num}: missing separator for key")

        raw_key = stripped[:sep_idx].strip()
        raw_value = stripped[sep_idx + 1:]

        # Handle inline comments (not inside quotes)
        value_with_inline_comment_removed = _remove_inline_comment(raw_value)

        # Process the value: handle quoting and trimming
        final_value = _process_value(value_with_inline_comment_removed)

        key_lower = raw_key.lower()

        if current_section not in result:
            result[current_section] = {}

        # Store for potential continuation
        last_entry_info = (current_section, key_lower, final_value, line_num)

        i += 1

    # Finalize any remaining entry
    if last_entry_info is not None:
        _finalize_entry(result, last_entry_info)

    # Remove empty sections (those with no keys)
    result = {k: v for k, v in result.items() if v}

    # Perform interpolation
    _interpolate(result)

    return result


def _remove_inline_comment(value_str: str) -> str:
    """Remove inline comments from a value string. Comments are ' #' or ' ;' not inside quotes."""
    in_quotes = False
    for ci, ch in enumerate(value_str):
        if ch == '"':
            in_quotes = not in_quotes
        elif not in_quotes and (ch == '#' or ch == ';'):
            # Check if there's whitespace before this marker
            if ci > 0 and value_str[ci - 1] in (' ', '\t'):
                return value_str[:ci].rstrip()
    return value_str


def _process_value(value_str: str) -> str:
    """Process a value string: trim, handle quotes."""
    trimmed = value_str.strip()

    if not trimmed:
        return ""

    # Check if fully wrapped in double quotes
    if len(trimmed) >= 2 and trimmed[0] == '"' and trimmed[-1] == '"':
        inner = trimmed[1:-1]
        # Unescape \" to "
        inner = inner.replace('\\"', '"')
        return inner

    # Otherwise, just trim
    return trimmed


def _finalize_entry(result: dict[str, dict[str, str]], info: tuple) -> None:
    """Finalize an entry and store it in the result."""
    section, key, value, line_num = info
    if section not in result:
        result[section] = {}
    result[section][key] = value


def _interpolate(result: dict[str, dict[str, str]]) -> None:
    """Perform interpolation on all values."""
    # For each section and key, resolve ${key} and ${section:key} references

    # We need to handle recursive resolution and detect cycles.

    def resolve_value(value: str, resolving_keys: set) -> str:
        """Resolve interpolation placeholders in a value string."""
        if '${' not in value and '$$' not in value:
            return value

        result_parts = []
        i = 0
        while i < len(value):
            if value[i] == '$':
                if i + 1 < len(value) and value[i + 1] == '$':
                    # Literal $$
                    result_parts.append('$')
                    i += 2
                elif i + 1 < len(value) and value[i + 1] == '{':
                    # Interpolation ${...}
                    close_idx = value.find('}', i + 2)
                    if close_idx == -1:
                        raise ValueError(f"Unterminated interpolation reference")
                    ref_str = value[i + 2:close_idx]

                    # Resolve the reference
                    resolved = resolve_reference(ref_str, resolving_keys)
                    result_parts.append(resolved)
                    i = close_idx + 1
                else:
                    # Just a $ not followed by $ or {
                    result_parts.append('$')
                    i += 1
            else:
                result_parts.append(value[i])
                i += 1

        return ''.join(result_parts)

    def resolve_reference(ref_str: str, resolving_keys: set) -> str:
        """Resolve a reference like 'key' or 'section:key'."""
        if ':' in ref_str:
            parts = ref_str.split(':', 1)
            sec_name = parts[0]
            key_name = parts[1].lower()
            if sec_name not in result:
                raise ValueError(f"Undefined section '{sec_name}' in reference")
            if key_name not in result[sec_name]:
                raise ValueError(f"Undefined key '{key_name}' in section '{sec_name}'")
            ref_key = (sec_name, key_name)
        else:
            key_name = ref_str.lower()
            # Look in current context... but we don't have current context here.
            # Actually, ${key} refers to the same section. But resolve_reference is called
            # during resolution of a specific value. We need to know which section/key we're resolving.
            # Let me rethink this.
            raise ValueError(f"Cannot resolve reference without context: {ref_str}")

        if ref_key in resolving_keys:
            raise ValueError(f"Reference cycle detected involving key '{ref_key}'")

        sec, key = ref_key
        raw_value = result[sec][key]
        new_resolving = resolving_keys | {ref_key}
        return resolve_value(raw_value, new_resolving)

    # We need to track which section/key we're currently resolving.
    # Let's restructure: for each (section, key), resolve its value.

    resolved_cache: dict[tuple[str, str], str] = {}

    def resolve_key(section: str, key: str) -> str:
        """Resolve a specific key's value, handling interpolation."""
        cache_key = (section, key)
        if cache_key in resolved_cache:
            return resolved_cache[cache_key]

        if section not in result or key not in result[section]:
            raise ValueError(f"Undefined key '{key}' in section '{section}'")

        raw_value = result[section][key]

        # Check for ${} references
        def resolve_in_context(value: str, resolving_keys: set) -> str:
            """Resolve interpolation placeholders in a value string, knowing the current section."""
            if '${' not in value and '$$' not in value:
                return value

            result_parts = []
            i = 0
            while i < len(value):
                if value[i] == '$':
                    if i + 1 < len(value) and value[i + 1] == '$':
                        # Literal $$
                        result_parts.append('$')
                        i += 2
                    elif i + 1 < len(value) and value[i + 1] == '{':
                        # Interpolation ${...}
                        close_idx = value.find('}', i + 2)
                        if close_idx == -1:
                            raise ValueError(f"Unterminated interpolation reference in key ({section}, {key})")
                        ref_str = value[i + 2:close_idx]

                        # Resolve the reference
                        resolved = resolve_ref_in_context(ref_str, section, resolving_keys)
                        result_parts.append(resolved)
                        i = close_idx + 1
                    else:
                        # Just a $ not followed by $ or {
                        result_parts.append('$')
                        i += 1
                else:
                    result_parts.append(value[i])
                    i += 1

            return ''.join(result_parts)

        def resolve_ref_in_context(ref_str: str, current_section: str, resolving_keys: set) -> str:
            """Resolve a reference string like 'key' or 'section:key'."""
            if ':' in ref_str:
                parts = ref_str.split(':', 1)
                sec_name = parts[0]
                key_name = parts[1].lower()
                if sec_name not in result:
                    raise ValueError(f"Undefined section '{sec_name}' in reference")
                if key_name not in result[sec_name]:
                    raise ValueError(f"Undefined key '{key_name}' in section '{sec_name}'")
                ref_key = (sec_name, key_name)
            else:
                key_name = ref_str.lower()
                # Same section
                sec_name = current_section
                if key_name not in result.get(sec_name, {}):
                    raise ValueError(f"Undefined key '{key_name}' in section '{sec_name}'")
                ref_key = (sec_name, key_name)

            if ref_key in resolving_keys:
                raise ValueError(f"Reference cycle detected involving key {ref_key}")

            # Resolve the referenced key recursively
            resolved_value = resolve_key(ref_key[0], ref_key[1])
            return resolved_value

        new_resolving = resolving_keys | {(section, key)}
        resolved = resolve_in_context(raw_value, new_resolving)

        resolved_cache[cache_key] = resolved
        result[section][key] = resolved
        return resolved

    # Resolve all keys
    for section in list(result.keys()):
        for key in list(result[section].keys()):
            resolve_key(section, key)


