import re
from typing import List, Optional, Tuple


class Version:
    """Represents a SemVer 2.0.0 version."""

    def __init__(self, major: int, minor: int, patch: int, prerelease: Optional[str] = None, build: Optional[str] = None):
        self.major = major
        self.minor = minor
        self.patch = patch
        self.prerelease = prerelease
        self.build = build

    @classmethod
    def parse(cls, v: str) -> 'Version':
        """Parse a SemVer string into a Version object."""
        if not isinstance(v, str):
            raise ValueError(f"Invalid version: {v}")

        s = v.strip()
        # Remove leading 'v' or '='
        if s.startswith('v') or s.startswith('='):
            s = s[1:]

        # SemVer regex pattern
        # Major.Minor.Patch[-Prerelease][+Build]
        pattern = r'^(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z\-]+(?:\.[0-9A-Za-z\-]+)*))?(?:\+([0-9A-Za-z\-]+(?:\.[0-9A-Za-z\-]+)*))?$'

        match = re.match(pattern, s)
        if not match:
            raise ValueError(f"Invalid SemVer version: {v}")

        major = int(match.group(1))
        minor = int(match.group(2))
        patch = int(match.group(3))
        prerelease = match.group(4)
        build = match.group(5)

        # Validate no leading zeros in numeric parts
        if len(match.group(1)) > 1 and match.group(1).startswith('0'):
            raise ValueError(f"Invalid SemVer version (leading zero in major): {v}")
        if len(match.group(2)) > 1 and match.group(2).startswith('0'):
            raise ValueError(f"Invalid SemVer version (leading zero in minor): {v}")
        if len(match.group(3)) > 1 and match.group(3).startswith('0'):
            raise ValueError(f"Invalid SemVer version (leading zero in patch): {v}")

        # Validate prerelease identifiers
        if prerelease is not None:
            identifiers = prerelease.split('.')
            for ident in identifiers:
                if not ident:
                    raise ValueError(f"Invalid SemVer version (empty prerelease identifier): {v}")
                if not re.match(r'^[0-9A-Za-z\-]+$', ident):
                    raise ValueError(f"Invalid SemVer version (invalid prerelease identifier '{ident}'): {v}")
                # Numeric identifiers must not have leading zeros
                if re.match(r'^\d+$', ident) and len(ident) > 1 and ident.startswith('0'):
                    raise ValueError(f"Invalid SemVer version (leading zero in numeric prerelease identifier): {v}")

        # Validate build metadata
        if build is not None:
            identifiers = build.split('.')
            for ident in identifiers:
                if not ident:
                    raise ValueError(f"Invalid SemVer version (empty build identifier): {v}")
                if not re.match(r'^[0-9A-Za-z\-]+$', ident):
                    raise ValueError(f"Invalid SemVer version (invalid build identifier '{ident}'): {v}")

        return cls(major, minor, patch, prerelease, build)

    def __repr__(self):
        s = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease is not None:
            s += f"-{self.prerelease}"
        if self.build is not None:
            s += f"+{self.build}"
        return s

    def _prerelease_tuple(self) -> tuple:
        """Convert prerelease to a tuple for comparison."""
        if self.prerelease is None:
            return ()  # Release versions have no prerelease, so they are greater than any prerelease

        identifiers = self.prerelease.split('.')
        result = []
        for ident in identifiers:
            if re.match(r'^\d+$', ident):
                result.append((0, int(ident), ''))  # (type, numeric_value, str_value) - type 0 for numeric
            else:
                result.append((1, 0, ident))  # type 1 for alphanumeric
        return tuple(result)

    def __eq__(self, other):
        if not isinstance(other, Version):
            return False
        return (self.major == other.major and 
                self.minor == other.minor and 
                self.patch == other.patch and 
                self.prerelease == other.prerelease)

    def __hash__(self):
        return hash((self.major, self.minor, self.patch, self.prerelease))

    def _precedence_tuple(self) -> tuple:
        """Return a tuple for comparing versions by SemVer precedence."""
        # Build metadata is ignored for precedence

        prerelease_tuple = self._prerelease_tuple()

        if self.prerelease is None:
            # Release version is greater than any prerelease with the same major.minor.patch
            # So we use a tuple that indicates "no prerelease" which should be > any prerelease
            return (self.major, self.minor, self.patch, 1)  # 1 for release
        else:
            # Prerelease version: compare identifiers
            # We need to compare the prerelease identifiers properly
            # The tuple comparison will work if we structure it correctly
            return (self.major, self.minor, self.patch, 0, prerelease_tuple)

    def __lt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented

        self_prec = self._precedence_tuple()
        other_prec = other._precedence_tuple()

        # Compare major.minor.patch first
        if self.major != other.major:
            return self.major < other.major
        if self.minor != other.minor:
            return self.minor < other.minor
        if self.patch != other.patch:
            return self.patch < other.patch

        # Same major.minor.patch, compare prerelease
        # No prerelease (release) is greater than any prerelease
        if self.prerelease is None and other.prerelease is not None:
            return False
        if self.prerelease is not None and other.prerelease is None:
            return True

        # Both have prerelease, compare identifiers
        self_ids = self._prerelease_tuple()
        other_ids = other._prerelease_tuple()

        for i in range(min(len(self_ids), len(other_ids))):
            s_type, s_num, s_str = self_ids[i]
            o_type, o_num, o_str = other_ids[i]

            if s_type != o_type:
                # Numeric < Alphanumeric
                return s_type < o_type

            if s_type == 0:
                # Both numeric
                if s_num != o_num:
                    return s_num < o_num
            else:
                # Both alphanumeric, ASCII order
                if s_str != o_str:
                    return s_str < o_str

        # All compared identifiers are equal, shorter list is smaller
        return len(self_ids) < len(other_ids)

    def __le__(self, other):
        return self == other or self < other

    def __gt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return not (self <= other)

    def __ge__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return not (self < other)


def _parse_version_or_partial(v: str) -> Tuple[Version, bool]:
    """Parse a version string that might be partial (e.g., 1.2.x).

    Returns (version, is_partial) where is_partial indicates if it's a partial version.
    For partial versions, we fill in missing parts with 0.
    """
    s = v.strip()
    # Remove leading 'v' or '='
    if s.startswith('v') or s.startswith('='):
        s = s[1:]

    # Check for X-ranges: x, X, *, etc.
    # Handle cases like "1.x", "1.2.x", "1.X", "1.2.X", "X", "*"
    is_partial = False

    # Normalize to lowercase for checking 'x' or '*'
    s_lower = s.lower()

    parts = s.split('.')
    if len(parts) == 1:
        part = parts[0]
        if part in ('*', 'x', 'X'):
            return (Version(0, 0, 0), True)
        elif re.match(r'^\d+$', part):
            return (Version(int(part), 0, 0), True)
        else:
            raise ValueError(f"Invalid version part: {part}")
    elif len(parts) == 2:
        p1, p2 = parts
        if p2 in ('*', 'x', 'X'):
            if not re.match(r'^\d+$', p1):
                raise ValueError(f"Invalid version: {v}")
            return (Version(int(p1), 0, 0), True)
        elif re.match(r'^\d+$', p1) and re.match(r'^\d+$', p2):
            return (Version(int(p1), int(p2), 0), False)
        else:
            raise ValueError(f"Invalid version: {v}")
    elif len(parts) == 3:
        p1, p2, p3 = parts
        if p3 in ('*', 'x', 'X'):
            if not (re.match(r'^\d+$', p1) and re.match(r'^\d+$', p2)):
                raise ValueError(f"Invalid version: {v}")
            return (Version(int(p1), int(p2), 0), True)
        elif re.match(r'^\d+$', p1) and re.match(r'^\d+$', p2) and re.match(r'^\d+$', p3):
            return (Version(int(p1), int(p2), int(p3)), False)
        else:
            raise ValueError(f"Invalid version: {v}")
    elif len(parts) > 3:
        # Check if all parts after the first few are x/X/*
        # e.g., "1.2.3.x" is not standard, but let's handle it as partial
        # Actually, SemVer only has major.minor.patch, so anything beyond that is invalid unless it's part of prerelease
        # But for X-ranges, we only support up to 3 parts with trailing x/X/*
        raise ValueError(f"Invalid version: {v}")
    else:
        raise ValueError(f"Invalid version: {v}")


def _compare_versions(v1: Version, v2: Version) -> int:
    """Compare two versions. Returns -1, 0, or 1."""
    if v1 < v2:
        return -1
    elif v1 > v2:
        return 1
    else:
        return 0


def _satisfies_single(version: Version, comparator: str, target: Version, is_partial_target: bool) -> bool:
    """Check if a version satisfies a single comparator."""
    op = comparator.strip()

    if not op or op == '=':
        # Equality check
        if is_partial_target:
            # For partial versions like "1.2", it means >=1.2.0 <1.3.0
            # But for a single comparator with '=', it's just exact match
            # Actually, "=" followed by a partial version should be treated as exact match to the filled version
            return _compare_versions(version, target) == 0
        else:
            return _compare_versions(version, target) == 0

    elif op == '<':
        if is_partial_target:
            # <1.2 means <1.2.0
            lower = Version(target.major, target.minor, target.patch)
            return _compare_versions(version, lower) < 0
        else:
            return _compare_versions(version, target) < 0

    elif op == '<=':
        if is_partial_target:
            # <=1.2 means <1.3.0 (exclusive of next minor)
            upper = Version(target.major, target.minor + 1, 0)
            return _compare_versions(version, upper) < 0
        else:
            return _compare_versions(version, target) <= 0

    elif op == '>':
        if is_partial_target:
            # >1.2 means >=1.3.0
            lower = Version(target.major, target.minor + 1, 0)
            return _compare_versions(version, lower) >= 0
        else:
            return _compare_versions(version, target) > 0

    elif op == '>=':
        if is_partial_target:
            # >=1.2 means >=1.2.0
            lower = Version(target.major, target.minor, target.patch)
            return _compare_versions(version, lower) >= 0
        else:
            return _compare_versions(version, target) >= 0

    else:
        raise ValueError(f"Invalid comparator: {op}")


def _has_prerelease_in_set(comparators: List[Tuple[str, Version, bool]]) -> bool:
    """Check if any comparator in the set has a version with prerelease."""
    for op, target, is_partial in comparators:
        if target.prerelease is not None:
            return True
    return False


def _version_has_same_major_minor_patch_as_any_comparator_target(version: Version, comparators: List[Tuple[str, Version, bool]]) -> bool:
    """Check if the version has the same major.minor.patch as any comparator target."""
    for op, target, is_partial in comparators:
        if version.major == target.major and version.minor == target.minor and version.patch == target.patch:
            return True
    return False


def _prerelease_satisfies_set(version: Version, comparators: List[Tuple[str, Version, bool]]) -> bool:
    """Check if a prerelease version satisfies all comparators in the set, considering prerelease rules."""
    # A prerelease version must satisfy all comparators
    for op, target, is_partial in comparators:
        if not _satisfies_single(version, op, target, is_partial):
            return False

    # Additionally, for a prerelease to be considered, some comparator in the set must have a version with the same major.minor.patch and a prerelease
    # If no comparator has a prerelease at the same major.minor.patch, then the prerelease version does not satisfy the set
    if version.prerelease is not None:
        if not _version_has_same_major_minor_patch_as_any_comparator_target(version, comparators):
            return False

    return True


def _version_satisfies_set(version: Version, comparators: List[Tuple[str, Version, bool]]) -> bool:
    """Check if a version satisfies all comparators in a set."""
    for op, target, is_partial in comparators:
        if not _satisfies_single(version, op, target, is_partial):
            return False

    # Handle prerelease logic
    if version.prerelease is not None:
        return _prerelease_satisfies_set(version, comparators)

    return True


def _parse_comparator(comp_str: str) -> Tuple[str, Version, bool]:
    """Parse a comparator string like '>=1.2.3' or '~1.2.x'."""
    comp_str = comp_str.strip()
    if not comp_str:
        raise ValueError("Empty comparator")

    # Extract operator
    op = ''
    rest = comp_str

    if comp_str.startswith('>='):
        op = '>='
        rest = comp_str[2:]
    elif comp_str.startswith('<='):
        op = '<='
        rest = comp_str[2:]
    elif comp_str.startswith('>'):
        op = '>'
        rest = comp_str[1:]
    elif comp_str.startswith('<'):
        op = '<'
        rest = comp_str[1:]
    elif comp_str.startswith('='):
        op = '='
        rest = comp_str[1:]

    if not rest:
        raise ValueError(f"Invalid comparator: {comp_str}")

    # Parse version part
    # Check for tilde, caret, or hyphen ranges first (they are separate tokens in the grammar)
    # But here we're parsing a single comparator, so it should be just an operator + version

    try:
        target, is_partial = _parse_version_or_partial(rest)
    except ValueError as e:
        raise ValueError(f"Invalid version in comparator '{comp_str}': {e}")

    return (op, target, is_partial)


def _parse_hyphen_range(hyphen_str: str) -> List[Tuple[str, Version, bool]]:
    """Parse a hyphen range like '1.2.3 - 2.3.4'."""
    parts = hyphen_str.split('-')
    if len(parts) != 2:
        raise ValueError(f"Invalid hyphen range: {hyphen_str}")

    lower_str = parts[0].strip()
    upper_str = parts[1].strip()

    if not lower_str or not upper_str:
        raise ValueError(f"Invalid hyphen range: {hyphen_str}")

    # Parse lower bound
    try:
