                    raise ValueError(f"Invalid tilde range in range '{rng}': {e}")
                i += 1
            elif token.startswith('^'):
                # Caret range
                caret_str = token
                try:
                    comp_set = _parse_caret_range(caret_str)
                    comparators.extend(comp_set)
                except ValueError as e:
                    raise ValueError(f"Invalid caret range in range '{rng}': {e}")
                i += 1
            else:
                # Regular comparator
                try:
                    comp = _parse_comparator(token)
                    comparators.append(comp)
                except ValueError as e:
                    raise ValueError(f"Invalid comparator in range '{rng}': {e}")
                i += 1

        sets.append(comparators)

    return sets


def satisfies(version_str: str, rng_str: str) -> bool:
    """Check if a version satisfies a range."""
    try:
        version = Version.parse(version_str)
    except ValueError as e:
        raise ValueError(f"Invalid version: {e}")

    try:
        sets = _parse_range(rng_str)
    except ValueError as e:
        raise ValueError(f"Invalid range: {e}")

    # Check if any set matches
    for comp_set in sets:
        if _version_satisfies_set(version, comp_set):
            return True

    return False


def max_satisfying(versions: List[str], rng: str) -> Optional[str]:
    """Find the maximum version that satisfies the range."""
    try:
        parsed_versions = []
        for v_str in versions:
            try:
                v = Version.parse(v_str)
                parsed_versions.append((v, v_str))
            except ValueError:
                continue

        # Filter versions that satisfy the range
        satisfying = []
        for v, v_str in parsed_versions:
            if satisfies(v_str, rng):
                satisfying.append((v, v_str))

        if not satisfying:
            return None

        # Find the maximum version by precedence
        max_v_obj = max(satisfying, key=lambda x: x[0])
        return max_v_obj[1]

    except ValueError as e:
        raise ValueError(f"Invalid range or version: {e}")
