def split_command(line: str, env: dict[str, str]) -> list[str]:
    """
    Implement a subset of POSIX shell word splitting and parameter expansion.

    Args:
        line: The command line string to parse.
        env: Environment variables dictionary.

    Returns:
        A list of words after parsing, expanding, and splitting.

    Raises:
        ValueError: For unterminated quotes, unterminated ${}, or trailing backslash.
    """

    def expand_variables(text: str) -> str:
        """
        Expand $NAME, ${NAME}, ${NAME:-default}, ${NAME-default} in text.
        This function is used for unquoted text and double-quoted text content.
        For double-quoted text, escape handling is done before calling this function.
        """
        result = []
        i = 0
        n = len(text)

        while i < n:
            if text[i] == '$':
                # Check what follows $
                if i + 1 >= n:
                    # Trailing $ is literal
                    result.append('$')
                    i += 1
                elif text[i + 1] == '{':
                    # ${...} expansion
                    j = i + 2
                    # Find the closing }
                    depth = 1
                    while j < n and depth > 0:
                        if text[j] == '}':
                            depth -= 1
                            if depth == 0:
                                break
                        elif text[j] == '{':
                            depth += 1
                        j += 1

                    if depth != 0:
                        raise ValueError("Unterminated ${}")

                    # Extract the content between { and }
                    content = text[i + 2:j]

                    # Parse the variable name and optional modifier
                    var_name, default_value, use_default_for_empty = parse_variable_expression(content)

                    # Get the value from env
                    if var_name in env:
                        val = env[var_name]
                    else:
                        val = None  # Unset

                    if val is not None and (use_default_for_empty or val != ''):
                        # Use the variable's value
                        result.append(val)
                    else:
                        # Use default
                        if default_value is not None:
                            # The default text undergoes $ expansion
                            expanded_default = expand_variables(default_value)
                            result.append(expanded_default)

                    i = j + 1

                elif text[i + 1].isalpha() or text[i + 1] == '_':
                    # $NAME expansion
                    j = i + 2
                    while j < n and (text[j].isalnum() or text[j] == '_'):
                        j += 1

                    var_name = text[i + 1:j]

                    if var_name in env:
                        result.append(env[var_name])
                    else:
                        # Unset variables expand to empty string
                        result.append('')

                    i = j

                else:
                    # $ not followed by name or { is literal
                    result.append('$')
                    i += 1
            else:
                result.append(text[i])
                i += 1

        return ''.join(result)

    def parse_variable_expression(content: str) -> tuple[str, str | None, bool]:
        """
        Parse ${NAME:-default} or ${NAME-default} or ${NAME}.
        Returns (var_name, default_value_or_None, use_default_for_empty).
        """
        # Find the variable name part
        i = 0
        n = len(content)

        # Variable name starts with [A-Za-z_][A-Za-z0-9_]*
        if i >= n or not (content[i].isalpha() or content[i] == '_'):
            raise ValueError(f"Invalid variable name in expression: {content}")

        j = i + 1
        while j < n and (content[j].isalnum() or content[j] == '_'):
            j += 1

        var_name = content[i:j]

        if j >= n:
            # Just ${NAME}
            return (var_name, None, False)

        rest = content[j:]

        if rest.startswith(':-'):
            # ${NAME:-default} - default if unset or empty
            default_part = rest[2:]
            return (var_name, default_part, True)
        elif rest.startswith('-'):
            # ${NAME-default} - default only if unset
            default_part = rest[1:]
            return (var_name, default_part, False)
        else:
            raise ValueError(f"Invalid variable expression modifier: {rest}")

    def parse_line(line: str) -> list[str]:
        """
        Parse the command line into words according to POSIX rules.
        """
        words = []
        i = 0
        n = len(line)

        while i < n:
            # Skip whitespace (unquoted spaces, tabs, newlines)
            if line[i] in ' \t\n':
                i += 1
                continue

            # Start building a word
            word_parts = []

            while i < n and line[i] not in ' \t\n':
                if line[i] == "'":
                    # Single quoted string: everything literal up to next '
                    i += 1  # skip opening '
                    start = i
                    while i < n and line[i] != "'":
                        i += 1
                    if i >= n:
                        raise ValueError("Unterminated single quote")
                    # i is now at the closing '
                    word_parts.append(line[start:i])
                    i += 1  # skip closing '

                elif line[i] == '"':
                    # Double quoted string
                    i += 1  # skip opening "
                    start = i
                    while i < n and line[i] != '"':
                        if line[i] == '\\' and i + 1 < n:
                            next_char = line[i + 1]
                            if next_char in ('$', '"', '\\', '\n'):
                                # Escape sequence
                                if next_char == '\n':
                                    # Backslash-newline removed
                                    pass
                                else:
                                    word_parts.append(next_char)
                                i += 2
                            else:
                                # Other backslash stays as is
                                word_parts.append('\\')
                                i += 1
                        else:
                            i += 1

                    if i >= n:
                        raise ValueError("Unterminated double quote")

                    # Extract the content between quotes
                    quoted_content = line[start:i]

                    # Expand variables inside double quotes
                    expanded = expand_variables(quoted_content)
                    word_parts.append(expanded)

                    i += 1  # skip closing "

                elif line[i] == '\\' and i + 1 < n:
                    # Unquoted backslash: escapes the next character
                    # Check if it's a backslash-newline (remove entirely)
                    if line[i + 1] == '\n':
                        # Backslash-newline is removed entirely
                        i += 2
                    else:
                        word_parts.append(line[i + 1])
                        i += 2
                elif line[i] == '\\' and i + 1 >= n:
                    # Trailing backslash
                    raise ValueError("Trailing unescaped backslash")
                else:
                    # Regular character, might be part of an unquoted expansion later
                    # We need to collect all consecutive non-whitespace, non-quote characters
                    start = i
                    while i < n and line[i] not in ' \t\n' and line[i] not in "'\"":
                        i += 1

                    # Extract the unquoted text
                    unquoted_text = line[start:i]

                    # Expand variables in unquoted text
                    expanded = expand_variables(unquoted_text)

                    # Field split the expanded result
                    if expanded:
                        parts = expanded.split()
                        for part in parts:
                            word_parts.append(part)
                    else:
                        # Empty unquoted expansion produces no words, so we don't add anything
                        pass

            # Now, word_parts contains all the components of this word.
            # Join them into a single word string.
            if word_parts:
                joined = ''.join(word_parts)
                words.append(joined)

        return words

    return parse_line(line)
