from __future__ import annotations

import dataclasses
import typing
from typing import Any, get_type_hints, get_origin, get_args


class LoadError(ValueError):
    """Exception raised when loading a dataclass from JSON-like data fails."""

    def __init__(self, path: str, message: str = ""):
        self.path = path
        if message:
            super().__init__(f"{path}: {message}")
        else:
            super().__init__(path)


def load(cls: type, data: Any) -> Any:
    """Load an instance of a dataclass from JSON-like data."""
    hints = get_type_hints(cls, localns={}, globalns={})
    return _load_with_path(cls, data, "$", hints)


def _load_with_path(cls: type, data: Any, path: str, hints: dict[str, Any] | None = None) -> Any:
    """Internal helper to load with path tracking."""
    # If cls is not a dataclass and hints are provided, we might be in a nested context
    # But typically cls should be the target type

    # Handle Optional[T] / T | None specially
    origin = get_origin(cls)
    args = get_args(cls)

    if origin is typing.Union or origin is type(typing.Optional[int]):  # Optional is Union[X, None]
        # Check if it's a union with None
        none_types = [t for t in args if t is type(None)]
        other_types = [t for t in args if t is not type(None)]

        if none_types and len(other_types) == 1:
            # It's Optional[T]
            inner_type = other_types[0]
            if data is None:
                return None
            else:
                try:
                    return _load_with_path(inner_type, data, path, hints)
                except LoadError:
                    raise

        if none_types and len(other_types) > 1:
            # It's a union with None and other types: T | U | None
            # Try non-None types first, left to right. If none work, try None.
            for t in other_types:
                try:
                    return _load_with_path(t, data, path, hints)
                except LoadError:
                    continue
            # If all non-None types failed, check if None is acceptable
            if data is None:
                return None
            else:
                # All attempts failed. Raise the last error or a generic one
                raise LoadError(path, f"Could not load into any of {args}")

        if not none_types:
            # Pure union without None: T | U | V
            for t in other_types:
                try:
                    return _load_with_path(t, data, path, hints)
                except LoadError:
                    continue
            raise LoadError(path, f"Could not load into any of {args}")

    # Handle Literal[...]
    if origin is typing.Literal:
        literal_values = args
        # Check if data matches one of the literal values with correct type
        for lv in literal_values:
            if data == lv and type(data) is type(lv):
                return lv
        raise LoadError(path, f"Value {data!r} does not match any literal value in {args}")

    # Handle basic types
    if cls is int:
        if isinstance(data, bool):
            raise LoadError(path, "bool is not accepted for int")
        if isinstance(data, int):
            return data
        raise LoadError(path, f"Expected int, got {type(data).__name__}")

    if cls is float:
        if isinstance(data, bool):
            raise LoadError(path, "bool is not accepted for float")
        if isinstance(data, (int, float)):
            return float(data)
        raise LoadError(path, f"Expected float, got {type(data).__name__}")

    if cls is str:
        if isinstance(data, str):
            return data
        raise LoadError(path, f"Expected str, got {type(data).__name__}")

    if cls is bool:
        if isinstance(data, bool):
            return data
        raise LoadError(path, f"Expected bool, got {type(data).__name__}")

    if cls is type(None):
        if data is None:
            return None
        raise LoadError(path, f"Expected None, got {type(data).__name__}")

    # Handle list[T]
    if origin is list:
        if not isinstance(data, list):
            raise LoadError(path, f"Expected list, got {type(data).__name__}")
        if args:
            inner_type = args[0]
            result = []
            for i, item in enumerate(data):
                try:
                    result.append(_load_with_path(inner_type, item, f"{path}[{i}]", hints))
                except LoadError:
                    raise
            return result
        else:
            return data  # No type hint, just validate it's a list

    # Handle dict[str, T]
    if origin is dict:
        if not isinstance(data, dict):
            raise LoadError(path, f"Expected dict, got {type(data).__name__}")
        if args:
            key_type = args[0]
            value_type = args[1]
            # For dict, keys are always strings in JSON-like data? The problem says dict[str, T]
            # So we assume keys must be strings. But let's check key_type too.
            result = {}
            for k, v in data.items():
                try:
                    # Validate key type
                    if key_type is str and not isinstance(k, str):
                        raise LoadError(path, f"Expected dict key to be str, got {type(k).__name__}")
                    # For now, assume keys are strings as per JSON. If key_type is something else, we might need to load it too.
                    # But the problem says `dict[str, T]`, so key is always str.
                    loaded_v = _load_with_path(value_type, v, f"{path}.{k}", hints)
                    result[k] = loaded_v
                except LoadError:
                    raise
            return result
        else:
            return data

    # Handle tuple[T, ...] (variable length)
    if origin is tuple:
        if not isinstance(data, list):
            raise LoadError(path, f"Expected list for tuple, got {type(data).__name__}")
        args_tuple = args
        if len(args_tuple) == 1 and args_tuple[0] is Ellipsis:
            # Variable length tuple: tuple[T, ...]
            inner_type = args_tuple[0]  # This will be the first arg, but we need to check for Ellipsis
            # Actually, get_args for tuple[int, ...] returns (int, Ellipsis)
            # Let me re-check. For `tuple[int, ...]`, get_args returns `(int, <class 'EllipsisType'>)`? No.
            # In Python 3.9+, typing.get_args(tuple[int, ...]) returns (int, Ellipsis)
            # But we need to detect the pattern. Let's handle it differently.
            pass

        # Check if it's variable length: tuple[T, ...]
        is_variable_length = False
        inner_type_for_var = None
        if args_tuple and len(args_tuple) == 2 and args_tuple[1] is Ellipsis:
            is_variable_length = True
            inner_type_for_var = args_tuple[0]

        if is_variable_length:
            result = []
            for i, item in enumerate(data):
                try:
                    result.append(_load_with_path(inner_type_for_var, item, f"{path}[{i}]", hints))
                except LoadError:
                    raise
            return tuple(result)
        else:
            # Fixed length tuple: tuple[A, B, C]
            if len(args_tuple) != len(data):
                raise LoadError(path, f"Expected tuple of length {len(args_tuple)}, got {len(data)}")
            result = []
            for i, item in enumerate(data):
                try:
                    result.append(_load_with_path(args_tuple[i], item, f"{path}[{i}]", hints))
                except LoadError:
                    raise
            return tuple(result)

    # Handle nested dataclasses
    if dataclasses.is_dataclass(cls):
        if not isinstance(data, dict):
            raise LoadError(path, f"Expected dict for dataclass {cls.__name__}, got {type(data).__name__}")

        # Get field info
        fields = dataclasses.fields(cls)
        field_map = {f.name: f for f in fields}

        # Get type hints for this dataclass
        if hints is None:
            hints = get_type_hints(cls, localns={}, globalns={})

        instance_dict = {}

        # Check for unknown keys first
        known_keys = set(field_map.keys())
        for key in data:
            if key not in known_keys:
                raise LoadError(f"{path}.{key}", f"Unknown field '{key}'")

        # Process each field
        for field in fields:
            field_name = field.name
            if field_name in data:
                try:
                    field_type = hints.get(field_name, Any)
                    value = _load_with_path(field_type, data[field_name], f"{path}.{field_name}", hints)
                except LoadError:
                    raise
                instance_dict[field_name] = value
            else:
                # Missing key
                if field.default is not dataclasses.MISSING:
                    instance_dict[field_name] = field.default
                elif field.default_factory is not dataclasses.MISSING:
                    instance_dict[field_name] = field.default_factory()
                else:
                    raise LoadError(f"{path}.{field_name}", f"Missing required field '{field_name}'")

        return cls(**instance_dict)

    # If we reach here, the type is not supported
    raise LoadError(path, f"Unsupported type {cls}")
