    len = length(rec)
    pos = 1

    while (pos <= len + 1) {
        nf++
        field = ""

        if (pos > len) {
            # Trailing empty field or end of record
            fields[nf] = ""
            break
        }

        c = substr(rec, pos, 1)
        if (c == "\"") {
            # Quoted field
