            if (pos <= len) {
                c = substr(rec, pos, 1)
                if (c == delim) {
                    pos++
                } else if (c != "\n") {
                    # Skip until delimiter or newline (should not happen in valid CSV)
                    while (pos <= len) {
                        c = substr(rec, pos, 1)
                        if (c == delim || c == "\n") break
                        pos++
                    }
                }
            }
        } else {
            # Unquoted field
            while (pos <= len) {
                c = substr(rec, pos, 1)
                if (c == delim || c == "\n") {
                    break
                }
                field = field c
                pos++
            }
        }

        fields[nf] = field

        # Check if we hit a delimiter or newline
        if (pos <= len) {
            c = substr(rec, pos, 1)
            if (c == delim) {
                pos++
            } else if (c == "\n") {
                break
            }
        } else {
            break
        }
    }

    return nf
}
