#!/usr/bin/env bash

set -euo pipefail

# Default values
N=10
CASE_INSENSITIVE=false

# Function to print usage message to stderr and exit 2
usage() {
    echo "Usage: $0 [-n N] [-i]" >&2
    exit 2
}

# Parse options
while getopts ":n:i" opt; do
    case "$opt" in
        n)
            # Check if the argument is a valid positive integer
            if [[ -z "$OPTARG" ]] || ! [[ "$OPTARG" =~ ^[0-9]+$ ]] || [[ "$OPTARG" -le 0 ]]; then
                usage
            fi
            N="$OPTARG"
            ;;
        i)
            CASE_INSENSITIVE=true
            ;;
        :)
            # Option requires an argument
            usage
            ;;
        *)
            # Invalid option
            usage
            ;;
    esac
done

# Process stdin with awk
# We need to:
# 1. Read all input
# 2. Extract words (maximal runs of ASCII letters, digits, apostrophes)
# 3. Strip leading/trailing apostrophes
# 4. Ignore tokens that are only apostrophes (or empty after stripping)
# 5. If -i, lowercase the word
# 6. Count frequencies
# 7. Sort by count descending, then word ascending (byte order LC_ALL=C)
# 8. Print top N

awk -v n="$N" -v case_insensitive="$CASE_INSENSITIVE" '
BEGIN {
    # Nothing to initialize for associative array
}
{
    line = $0
    while (length(line) > 0) {
        # Find the start of a word: maximal run of [a-zA-Z0-9\047]
        # We need to scan character by character or use match

        # Try to find next potential word start
        # A word consists of ASCII letters, digits, and apostrophes (0x27)

        # Skip non-word characters
        while (length(line) > 0) {
            c = substr(line, 1, 1)
            if ((c >= "a" && c <= "z") || (c >= "A" && c <= "Z") || (c >= "0" && c <= "9") || c == "\047") {
                break
            }
            line = substr(line, 2)
        }

        if (length(line) == 0) break

        # Extract the maximal run of word characters
        word_str = ""
        while (length(line) > 0) {
            c = substr(line, 1, 1)
            if ((c >= "a" && c <= "z") || (c >= "A" && c <= "Z") || (c >= "0" && c <= "9") || c == "\047") {
                word_str = word_str c
                line = substr(line, 2)
            } else {
                break
            }
        }

        # Strip leading apostrophes
        while (length(word_str) > 0 && substr(word_str, 1, 1) == "\047") {
            word_str = substr(word_str, 2)
        }

        # Strip trailing apostrophes
        while (length(word_str) > 0 && substr(word_str, length(word_str), 1) == "\047") {
            word_str = substr(word_str, 1, length(word_str) - 1)
        }

        # Skip if empty or only apostrophes (already handled by stripping, but check if empty now)
        if (length(word_str) == 0) continue

        # If case insensitive, lowercase the word
        if (case_insensitive == "true") {
            # Convert to lowercase using awk built-in tolower
            word = tolower(word_str)
        } else {
            word = word_str
        }

        counts[word]++
    }
}
END {
    # Now we need to sort by count descending, then word ascending (byte order)
    # Since mawk does not have asort or PROCINFO, we need to do this manually

    # Collect all words into an array for sorting
    num_words = 0
    for (w in counts) {
        num_words++
        words[num_words] = w
        cnts[num_words] = counts[w]
    }

    # Simple selection sort or bubble sort since N is small and distinct words might not be huge
    # Actually, we need to output top N, so we can do a partial sort
    # Let us do a full sort using insertion sort which is O(n^2) but fine for reasonable inputs

    # Sort by count descending, then word ascending (byte order - ASCII order)
    for (i = 2; i <= num_words; i++) {
        w = words[i]
        c = cnts[i]
        j = i - 1

        # Compare: we want to insert (c, w) into the sorted portion [1..j]
        # Sorted order: higher count first, then lower word (ASCII) first
        while (j >= 1) {
            if (cnts[j] < c) {
                # cnts[j] is smaller, so (c,w) should come before j
                words[j+1] = words[j]
                cnts[j+1] = cnts[j]
                j--
            } else if (cnts[j] == c) {
                # Same count, compare words in byte order (ascending)
                # We want ascending word order, so if words[j] > w, then w comes first
                if (words[j] > w) {
                    words[j+1] = words[j]
                    cnts[j+1] = cnts[j]
                    j--
                } else {
                    break
                }
            } else {
                # cnts[j] > c, so (c,w) should come after j
                break
            }
        }
        words[j+1] = w
        cnts[j+1] = c
    }

    # Print top N
    limit = n
    if (num_words < limit) {
        limit = num_words
    }

    for (i = 1; i <= limit; i++) {
        print cnts[i] " " words[i]
    }
}
